<script setup>
import {s,canEdit,run,dateText,loadContactHistory} from './store';
import ListPager from './ListPager.vue';
const responses=[{value:'pending',label:'Chưa có phản hồi'},{value:'confirmed',label:'Xác nhận tham dự'},{value:'declined',label:'Không tham dự'},{value:'no_answer',label:'Không nghe máy'},{value:'call_back',label:'Hẹn liên hệ lại'}];
const channels=[{value:'phone',label:'Điện thoại'},{value:'paper',label:'Phiếu / giấy phản hồi'},{value:'email',label:'Email'},{value:'other',label:'Khác'}];
</script><template><div class="stack"><h3>{{s.editRow.name||'Khách chưa có tên'}}</h3><p>{{s.editRow.phone||'—'}} · {{s.editRow.company||'—'}}</p><label class="field">Cách liên hệ<MSelect v-model="s.contactDraft.channel" :options="channels" @update:model-value="s.contactDraft.called=$event==='phone'"/></label><MCheckbox v-if="s.contactDraft.channel==='phone'" v-model="s.contactDraft.called" label="Đã thực hiện cuộc gọi"/><label class="field">Phản hồi<MSelect v-model="s.contactDraft.response" :options="responses"/></label><label class="field">Ghi chú<MTextarea v-model="s.contactDraft.note"/></label><label v-if="s.contactDraft.response==='call_back'" class="field">Hẹn gọi lại<MInput v-model="s.contactDraft.follow_up_at" placeholder="dd/mm/yyyy hh:mm"/></label><h3>Lịch sử liên hệ</h3><p v-if="!s.contactHistory.length" class="muted">Chưa có liên hệ được ghi nhận trên ứng dụng.</p><template v-else><article v-for="item in s.contactHistory" :key="item.id" class="contact-entry"><strong>{{item.actor}}</strong><span class="muted"> · {{new Date(item.created_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})}} · {{channels.find(c=>c.value===item.channel)?.label}}</span><p>{{responses.find(r=>r.value===item.response)?.label}}<span v-if="item.called"> · Đã gọi</span></p><p v-if="item.note">{{item.note}}</p><p v-if="item.follow_up_at" class="muted">Hẹn: {{new Date(item.follow_up_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})}}</p></article><ListPager :total="s.contactTotal" :page="s.contactPage" :page-size="s.contactPageSize" @update:page-size="s.contactPageSize=$event" @update:page="s.contactPage=$event;run(loadContactHistory)"/></template></div></template>
